server {
       listen 80;
       listen [::]:80;
       server_name bottino;
       error_log  /var/log/nginx/error.log;
       access_log /var/log/nginx/access.log;
       root /var/www/html/;
       index index.html index.htm index.php;
    location ~ \.php$ {
      try_files $uri =404;
      fastcgi_split_path_info ^(.+\.php)(/.+)$;
      fastcgi_pass php_upstream;
      fastcgi_index index.php;
      fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;
      include /etc/nginx/fastcgi_params;
      include fastcgi.conf;
      fastcgi_param PATH_INFO $fastcgi_path_info;
     }
    location /api/ {
        #set $ollama_up "http://ollama:11434";
        #set $ollama_up "http://llama_cpp:8089";
        #proxy_pass $ollama_up$request_uri;
        proxy_pass http://ollama:11434;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_connect_timeout 60s;
        proxy_send_timeout 86400s;
        proxy_read_timeout 86400s;
        proxy_buffering off;
        proxy_cache off;
        chunked_transfer_encoding off;
        proxy_request_buffering off;
        proxy_intercept_errors on;
        error_page 502 503 = @ollama_unavailable;
    }
    # Ollama root
    location / {
        root /var/www/html/;
	index index.html;
        #set $ollama_up "http://ollama:11434";
	#set $ollama_up "http://llama_cpp:8089";
        #proxy_pass $ollama_up;
        # proxy_pass http://ollama:11434;
        # proxy_http_version 1.1;
        # proxy_set_header Host $host;
        # proxy_set_header X-Real-IP $remote_addr;
        # proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        # proxy_set_header X-Forwarded-Proto $scheme;
        # proxy_connect_timeout 60s;
        # proxy_send_timeout 86400s;
        # proxy_read_timeout 86400s;
        # proxy_buffering off;
        # proxy_cache off;
        # chunked_transfer_encoding off;
        # proxy_request_buffering off;
        # proxy_intercept_errors on;
        # error_page 502 503 = @ollama_unavailable;
    }
    location @ollama_unavailable {
        default_type text/plain;
        return 503 "Ollama server temporarily unavailable\n";
    }
    # return 301 https://$host$request_uri;
    # MCP: browsers open /mcp (no slash) → must not hit port 8000 (protocol only). Redirect to agent on 8001.
    location = /mcp-app/ {
        if ($request_method = GET) {
            return 301 $scheme://$host/mcp-server/;
        }
        if ($request_method = HEAD) {
            return 301 $scheme://$host/mcp-server/;
        }
        # POST etc. → MCP protocol server (Emacs / streamable-http). Literal upstream (no variable).
        proxy_pass http://mcp-server:8002;
        proxy_http_version 1.1;
        proxy_set_header Host $host:8002;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_connect_timeout 15s;
        proxy_send_timeout 120s;
        proxy_read_timeout 120s;
        proxy_buffering off;
        proxy_intercept_errors on;
        error_page 502 503 = @mcp_unavailable;
    }
    # No variable: nginx strips /mcp and forwards the rest to 8001. Requires mcp to be up (e.g. depends_on).
    location /mcp/ {
        proxy_pass http://mcp-server:8001/;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_connect_timeout 15s;
        proxy_send_timeout 180s;
        proxy_read_timeout 180s;
        proxy_buffering off;
        proxy_intercept_errors on;
        error_page 502 503 = @mcp_unavailable;
    }

}

